const item = $input.first().json;

const errors = [...(item.errors || [])];
const warnings = [...(item.warnings || [])];

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const fullLibraryText = toText(item.data);
const promptId = toText(item.prompt_id).trim();

if (!fullLibraryText.trim()) {
  addUnique(errors, "google_doc_text_is_empty");
}

if (!promptId) {
  addUnique(errors, "prompt_id_is_empty");
}

let extractedPromptText = "";
let promptExtractStatus = "failed";
let promptExtractError = "";

if (errors.length === 0) {
  const startMarker = `=== PROMPT_START: ${promptId} ===`;
  const endMarker = `=== PROMPT_END: ${promptId} ===`;

  const startIndex = fullLibraryText.indexOf(startMarker);
  const endIndex = fullLibraryText.indexOf(endMarker);

  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) {
    addUnique(errors, "prompt_markers_not_found");

    promptExtractError =
      `Markers not found for ${promptId}. Expected start: ${startMarker}; expected end: ${endMarker}`;
  } else {
    const contentStart = startIndex + startMarker.length;

    extractedPromptText = fullLibraryText
      .slice(contentStart, endIndex)
      .trim();

    promptExtractStatus = "success";
  }
}

if (!extractedPromptText.trim()) {
  addUnique(errors, "extracted_prompt_text_is_empty");
}

return [
  {
    json: {
      ...item,

      prompt_start_marker: `=== PROMPT_START: ${promptId} ===`,
      prompt_end_marker: `=== PROMPT_END: ${promptId} ===`,

      extracted_prompt_text: errors.length === 0 ? extractedPromptText : "",
      prompt_text: errors.length === 0 ? extractedPromptText : "",

      prompt_extract_status: errors.length === 0 ? "success" : "failed",
      prompt_extract_error: errors.length === 0 ? "" : promptExtractError || errors.join("; "),

      valid_extract: errors.length === 0,
      ready_for_prompt_builder: errors.length === 0,

      errors,
      warnings,

      next_step: errors.length === 0
        ? "Передать extracted_prompt_text в Prompt Builder."
        : "Проверить prompt_id, маркеры PROMPT_START/PROMPT_END и текст Google Doc."
    }
  }
];

const items = $input.all();

const placeholders = [
  "[ВСТАВИТЬ ТЕКСТ ТРЕБОВАНИЯ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ЗАДАЧИ ИЛИ ПРОЦЕССА]",
  "[ВСТАВИТЬ ЗАДАЧУ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ПРОБЛЕМЫ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ПРОЕКТА, ТРЕБОВАНИЯ, ПРОМПТОВ И РЕЗУЛЬТАТОВ]"
];

return items.map((item) => {
  const input = item.json || {};

  const errors = Array.isArray(input.errors) ? [...input.errors] : [];

  const warnings = [
  ...(Array.isArray(input.warnings) ? input.warnings : []),
  ...(Array.isArray(input.precheck_warnings) ? input.precheck_warnings : [])
];

  function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

  const promptId = input.prompt_id || "UNKNOWN_PROMPT";
  const inputId = input.input_id || "UNKNOWN_INPUT";

  const promptText = input.prompt_text || "";
  const requirementText = input.requirement_text || "";

  if (input.ready_for_prompt_builder !== true) {
    errors.push("prompt_is_not_ready_for_builder");
  }

  if (!promptText.trim()) {
    errors.push("prompt_text_is_empty");
  }

  if (!requirementText.trim()) {
    errors.push("requirement_text_is_empty");
  }

  let finalPrompt = promptText;
  let placeholderUsed = "";

  if (errors.length === 0) {
    for (const placeholder of placeholders) {
      if (finalPrompt.includes(placeholder)) {
        finalPrompt = finalPrompt.split(placeholder).join(requirementText.trim());
        placeholderUsed = placeholder;
        break;
      }
    }

    if (!placeholderUsed) {
      errors.push("placeholder_not_found");
    }
  }

  if (finalPrompt.includes("=== PROMPT_START:") || finalPrompt.includes("=== PROMPT_END:")) {
    addUnique(warnings, "final_prompt_contains_prompt_markers");
  }

  if (finalPrompt.includes("[ВСТАВИТЬ")) {
    addUnique(warnings, "final_prompt_may_contain_unreplaced_placeholder");
  }

  return {
    json: {
      ...input,
      builder_id: `BUILD-${inputId}-${promptId}`,
      placeholder_used: placeholderUsed || "not_found",
      final_prompt: errors.length === 0 ? finalPrompt : "",
      final_prompt_length: errors.length === 0 ? finalPrompt.length : 0,
      valid_prompt_build: errors.length === 0,
      ai_ready: errors.length === 0,
      prompt_builder_status: errors.length === 0 ? "built" : "failed",
      prompt_builder_error: errors.length === 0 ? null : errors.join(", "),
      errors,
      warnings,
      next_step: errors.length === 0
        ? "Передать final_prompt в AI-блок."
        : "Проверить prompt_text, requirement_text и placeholder перед запуском AI."
    }
  };
});

const item = $input.first().json || {};

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

const errors = Array.isArray(item.errors) ? [...item.errors] : [];

const warnings = [
  ...(Array.isArray(item.warnings) ? item.warnings : []),
  ...(Array.isArray(item.precheck_warnings) ? item.precheck_warnings : [])
];

const inputId = toText(item.input_id || "UNKNOWN_INPUT").trim();
const promptId = toText(item.prompt_id || "UNKNOWN_PROMPT").trim();
const routeId = toText(item.route_id || "").trim();

const requirementText = toText(item.requirement_text).trim();
const finalPrompt = toText(item.final_prompt).trim();

const finalPromptLength = finalPrompt.length;

if (!inputId || inputId === "UNKNOWN_INPUT") {
  addUnique(errors, "input_id_is_empty_or_unknown");
}

if (!promptId || promptId === "UNKNOWN_PROMPT") {
  addUnique(errors, "prompt_id_is_empty_or_unknown");
}

if (!routeId) {
  addUnique(errors, "route_id_is_empty");
}

if (!finalPrompt) {
  addUnique(errors, "final_prompt_is_empty");
}

if (!item.valid_prompt_build) {
  addUnique(errors, "valid_prompt_build_is_false");
}

if (!item.ai_ready) {
  addUnique(errors, "builder_ai_ready_is_false");
}

if (!requirementText && promptId !== "P011") {
  addUnique(errors, "requirement_text_is_empty");
}

const unreplacedPlaceholders = [
  "[ВСТАВИТЬ ТЕКСТ ТРЕБОВАНИЯ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ЗАДАЧИ ИЛИ ПРОЦЕССА]",
  "[ВСТАВИТЬ ЗАДАЧУ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ПРОБЛЕМЫ]",
  "[ВСТАВИТЬ ОПИСАНИЕ ПРОЕКТА, ТРЕБОВАНИЯ, ПРОМПТОВ И РЕЗУЛЬТАТОВ]"
];

for (const placeholder of unreplacedPlaceholders) {
  if (finalPrompt.includes(placeholder)) {
    addUnique(errors, "final_prompt_contains_unreplaced_placeholder");
    break;
  }
}

if (finalPrompt.includes("=== PROMPT_START:") || finalPrompt.includes("=== PROMPT_END:")) {
  addUnique(errors, "final_prompt_contains_prompt_library_markers");
}

if (finalPromptLength > 0 && finalPromptLength < 500) {
  addUnique(warnings, "final_prompt_length_suspiciously_short");
}

if (finalPromptLength > 15000) {
  addUnique(warnings, "final_prompt_length_is_large");
}

const forbiddenFragments = [
  "REMOVE ALL FORMATTING",
  "REMOVE ALL EXTERNAL REFERENCES",
  "ignore previous instructions",
  "Authorization:",
  "Bearer ",
  "access_token",
  "refresh_token"
];

for (const fragment of forbiddenFragments) {
  if (finalPrompt.toLowerCase().includes(fragment.toLowerCase())) {
    addUnique(errors, "final_prompt_contains_forbidden_fragment");
    break;
  }
}

const validForAi = errors.length === 0;

const {
  data,
  prompt_text,
  extracted_prompt_text,
  router_raw_content,
  ...cleanItem
} = item;

return [
  {
    json: {
      ...cleanItem,

      validation_id: `VAL-${inputId}-${promptId}`,

      input_id: inputId,
      route_id: routeId,
      prompt_id: promptId,

      prompt_number: item.prompt_number,
      prompt_name: item.prompt_name,
      expected_result_type: item.expected_result_type,

      requirement_text: requirementText,

      placeholder_used: item.placeholder_used,
      final_prompt: validForAi ? finalPrompt : "",
      final_prompt_length: finalPromptLength,

      valid_for_ai: validForAi,
      ai_ready: validForAi,

      prompt_build_validator_status: validForAi ? "passed" : "blocked",
      prompt_build_validator_errors: errors,
      prompt_build_validator_warnings: warnings,

      errors,
      warnings,

      next_step: validForAi
        ? "Передать final_prompt в GigaChat Request."
        : "Не запускать AI. Отправить в Human Review / Automation Log."
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      log_id: `LOG-AIRUN-${new Date().toISOString()}-${item.input_id || "UNKNOWN"}`,
      input_id: item.input_id || "",
      output_id: item.builder_id || "",
      date: new Date().toISOString(),
      trigger: "Prompt Build Validator",
      execution_status: "blocked",
      ai_status: "not_started",
      storage_status: "not_sent_to_ai",
      human_review: "required",
      error: (item.errors || []).join("; "),
      warnings: (item.warnings || []).join("; "),
      next_step: item.next_step || "Проверить входные данные перед запуском AI."
    }
  }
];

const item = $input.first().json;

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

const routerInput = getNodeJson("Prompt Router Input");
const buildRouterPrompt = getNodeJson("Build P010 Router Prompt");
const routerValidator = getNodeJson("Router Output Validator");
const promptRegistry = getNodeJson("Prompt Registry");

const errors = [...(item.errors || [])];
const warnings = [...(item.warnings || [])];

const inputId =
  item.input_id ||
  routerValidator.input_id ||
  promptRegistry.input_id ||
  routerInput.input_id ||
  buildRouterPrompt.input_id ||
  "UNKNOWN_INPUT";

const taskText = toText(
  item.task_text ||
  routerValidator.task_text ||
  promptRegistry.task_text ||
  routerInput.task_text ||
  buildRouterPrompt.task_text ||
  ""
).trim();

const currentStage = toText(
  item.current_stage ||
  routerValidator.current_stage ||
  promptRegistry.current_stage ||
  routerInput.current_stage ||
  buildRouterPrompt.current_stage ||
  ""
).trim();

const requirementText = toText(
  item.requirement_text ||
  routerValidator.requirement_text ||
  promptRegistry.requirement_text ||
  routerInput.requirement_text ||
  buildRouterPrompt.requirement_text ||
  ""
).trim();

const promptId = toText(
  item.prompt_id ||
  promptRegistry.prompt_id ||
  routerValidator.prompt_id ||
  ""
).trim();

const routeId = toText(
  item.route_id ||
  promptRegistry.route_id ||
  routerValidator.route_id ||
  ""
).trim();

if (!inputId || inputId === "UNKNOWN_INPUT") {
  addUnique(warnings, "input_id_was_restored_as_unknown");
}

if (!promptId) {
  addUnique(errors, "prompt_id_is_empty_before_prompt_extractor");
}

if (!requirementText && promptId !== "P011") {
  addUnique(errors, "requirement_text_is_empty_before_prompt_builder");
}
const mergedWarnings = [
  ...warnings,
  ...(
    Array.isArray(buildRouterPrompt.precheck_warnings)
      ? buildRouterPrompt.precheck_warnings
      : []
  ),
  ...(
    Array.isArray(buildRouterPrompt.warnings)
      ? buildRouterPrompt.warnings
      : []
  )
];

const uniqueWarnings = [...new Set(mergedWarnings)];

return [
  {
    json: {
      ...promptRegistry,
      ...item,

      input_id: inputId,
      task_text: taskText,
      current_stage: currentStage,
      requirement_text: requirementText,

      route_id: routeId,
      prompt_id: promptId,

      prompt_number: item.prompt_number || promptRegistry.prompt_number,
      prompt_name: item.prompt_name || promptRegistry.prompt_name,
      prompt_doc_url: item.prompt_doc_url || promptRegistry.prompt_doc_url,
      expected_result_type: item.expected_result_type || promptRegistry.expected_result_type,
      input_precheck_id: item.input_precheck_id || buildRouterPrompt.input_precheck_id,
      input_quality: item.input_quality || buildRouterPrompt.input_quality,
      input_quality_score: item.input_quality_score || buildRouterPrompt.input_quality_score,
      input_quality_reason: item.input_quality_reason || buildRouterPrompt.input_quality_reason,
      requirement_word_count: item.requirement_word_count || buildRouterPrompt.requirement_word_count,
      input_signal_score: item.input_signal_score || buildRouterPrompt.input_signal_score,
      input_signals: item.input_signals || buildRouterPrompt.input_signals,
      missing_data: item.missing_data || buildRouterPrompt.missing_data || [],
      safe_routes: item.safe_routes || buildRouterPrompt.safe_routes || [],
      blocked_routes: item.blocked_routes || buildRouterPrompt.blocked_routes || [],
      precheck_status: item.precheck_status || buildRouterPrompt.precheck_status,
      precheck_warnings: item.precheck_warnings || buildRouterPrompt.precheck_warnings || [],

      registry_status: item.registry_status || promptRegistry.registry_status,
      prompt_doc_url_valid: item.prompt_doc_url_valid ?? promptRegistry.prompt_doc_url_valid,
      ready_for_prompt_extract: item.ready_for_prompt_extract ?? promptRegistry.ready_for_prompt_extract,

      source_context_attached: true,

      errors,
      warnings: uniqueWarnings,

      next_step: errors.length === 0
        ? "Передать контекст в Prompt Extractor."
        : "Проверить исходный контекст, prompt_id и requirement_text перед Prompt Extractor."
    }
  }
];

const routerPrompt = $('Build P010 Router Prompt').first().json;
const tokenResponse = $input.first().json;

const errors = [];
const warnings = [];

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

const accessToken =
  tokenResponse.access_token ||
  tokenResponse.data?.access_token ||
  tokenResponse.body?.access_token ||
  "";

const finalPrompt = toText(routerPrompt.final_prompt).trim();

if (!accessToken) {
  errors.push("gigachat_access_token_is_empty");
}

if (!finalPrompt) {
  errors.push("router_final_prompt_is_empty");
}

if (routerPrompt.ai_ready !== true) {
  errors.push("router_prompt_ai_ready_is_false");
}

if ((routerPrompt.final_prompt_length || finalPrompt.length || 0) < 500) {
  warnings.push("router_final_prompt_length_suspiciously_short");
}

const systemMessage = [
  "Ты работаешь внутри автоматизированного n8n workflow.",
  "Твоя задача — вернуть только валидный JSON для выбора prompt_id.",
  "Не выполняй рабочую задачу пользователя.",
  "Не делай ревью требования.",
  "Не формируй вопросы заказчику.",
  "Не делай декомпозицию.",
  "Не оформляй портфолио-кейс.",
  "Выбери только route_id и prompt_id по переданному router prompt.",
  "Не добавляй Markdown.",
  "Не добавляй пояснения до или после JSON.",
  "Если не уверен в выборе, верни ROUTE_NEEDS_HUMAN_REVIEW и prompt_id null.",
  "human_review_required всегда true."
].join(" ");

const gigachatBody = {
  model: "GigaChat:2.0.28.2",
  messages: [
    {
      role: "system",
      content: systemMessage
    },
    {
      role: "user",
      content: finalPrompt
    }
  ],
  temperature: 0.1,
  top_p: 0.8,
  stream: false
};

return [
  {
    json: {
      request_id: `GCHATROUTERREQ-${routerPrompt.input_id || "UNKNOWN_INPUT"}-${routerPrompt.router_prompt_id || "P010"}`,

      input_id: routerPrompt.input_id,
      task_text: routerPrompt.task_text,
      current_stage: routerPrompt.current_stage,
      requirement_text: routerPrompt.requirement_text,

      router_prompt_id: routerPrompt.router_prompt_id || "P010",
      router_prompt_name: routerPrompt.router_prompt_name,
      expected_result_type: "router_decision",

      final_prompt: finalPrompt,
      final_prompt_length: finalPrompt.length,

      access_token: accessToken,

      gigachat_system_message: systemMessage,
      gigachat_body: gigachatBody,

      ready_for_gigachat: errors.length === 0,

      errors,
      warnings,

      next_step: errors.length === 0
        ? "Передать gigachat_body и access_token в GigaChat Router Call."
        : "Не запускать GigaChat Router Call. Записать ошибку в Automation Log."
    }
  }
];

const items = $input.all();

function cleanJsonString(value) {
return String(value || "")
.trim()
.replace(/^`json\s*/i, "")
    .replace(/^`\s*/i, "")
.replace(/```$/i, "")
.trim();
}

function extractContent(aiRaw) {
return (
aiRaw.choices?.[0]?.message?.content ||
aiRaw.message?.content ||
aiRaw.content ||
aiRaw.data?.choices?.[0]?.message?.content ||
aiRaw.body?.choices?.[0]?.message?.content ||
""
);
}

function uniqueArray(values) {
return [
...new Set(
(values || [])
.filter(value => value !== null && value !== undefined)
.map(value => String(value).trim())
.filter(Boolean)
)
];
}

return items.map((item) => {
const aiRaw = item.json || {};
const content = extractContent(aiRaw);

// Берём полный контекст, который пришёл в Router:
// Human Review, предыдущий output, предыдущий prompt/route,
// Precheck и исходное требование.
const source =
$("Build P010 Router Prompt").first().json || {};

const errors = [];
const warnings = [];

if (!content.trim()) {
errors.push("router_ai_content_is_empty");
}

let routerDecision = null;

if (errors.length === 0) {
try {
const cleaned = cleanJsonString(content);
routerDecision = JSON.parse(cleaned);
} catch (error) {
errors.push(
`router_json_parse_failed: ${error.message}`
);
}
}

// Неуспешный разбор Router JSON
if (errors.length > 0) {
return {
json: {
// Сохраняем весь входной контекст.
...source,

    router_parse_status: "failed",
    router_valid_json: false,
    router_raw_content: content,
    router_decision: null,

    errors: uniqueArray([
      ...(Array.isArray(source.errors)
        ? source.errors
        : []),
      ...errors
    ]),

    warnings: uniqueArray([
      ...(Array.isArray(source.warnings)
        ? source.warnings
        : []),
      ...warnings
    ]),

    next_step:
      "Не передавать в Prompt Registry. Отправить на Human Review / Manual Prompt Selection."
  }
};

}

// Успешный разбор Router JSON
return {
json: {
// Сначала сохраняем весь исходный контекст.
...source,
  // Затем накладываем новое решение Router.
  ...routerDecision,

  router_parse_status: "parsed",
  router_valid_json: true,
  router_raw_content: content,
  usage: aiRaw.usage || {},

  errors: [],

  warnings: uniqueArray([
    ...(Array.isArray(source.warnings)
      ? source.warnings
      : []),
    ...(Array.isArray(routerDecision?.warnings)
      ? routerDecision.warnings
      : []),
    ...warnings
  ]),

  next_step:
    "Передать в Router Output Validator."
}

};
});

const item = $input.first().json;

const errors = [...(item.errors || [])];
const warnings = [...(item.warnings || [])];

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

function normalizeCode(value) {
  return String(value || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-ZА-Я0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

const allowedRoutes = [
  "ROUTE_PROCESS_DESIGN",
  "ROUTE_REQUIREMENT_STRUCTURING",
  "ROUTE_TEST_DESIGN",
  "ROUTE_CUSTOMER_QUESTIONS",
  "ROUTE_USER_STORY_AC",
  "ROUTE_BUG_REPORT",
  "ROUTE_CHECKLIST",
  "ROUTE_REQUIREMENT_REVIEW",
  "ROUTE_REQUIREMENT_DECOMPOSITION",
  "ROUTE_PORTFOLIO_CASE",
  "ROUTE_NEEDS_HUMAN_REVIEW"
];

const allowedPrompts = [
  "P011",
  "P001",
  "P002",
  "P003",
  "P004",
  "P005",
  "P006",
  "P007",
  "P008",
  "P009",
  null
];

const routeToPrompt = {
  ROUTE_PROCESS_DESIGN: "P011",
  ROUTE_REQUIREMENT_STRUCTURING: "P001",
  ROUTE_TEST_DESIGN: "P002",
  ROUTE_CUSTOMER_QUESTIONS: "P003",
  ROUTE_USER_STORY_AC: "P004",
  ROUTE_BUG_REPORT: "P005",
  ROUTE_CHECKLIST: "P006",
  ROUTE_REQUIREMENT_REVIEW: "P007",
  ROUTE_REQUIREMENT_DECOMPOSITION: "P008",
  ROUTE_PORTFOLIO_CASE: "P009",
  ROUTE_NEEDS_HUMAN_REVIEW: null
};

const routerVersion = String(item.router_version || "").trim();
const normalizedRouteId = normalizeCode(item.route_id);
const promptId = item.prompt_id === undefined ? null : item.prompt_id;
const confidence = Number(item.confidence || 0);

let routeId = normalizedRouteId;

if (routerVersion !== "0.3") {
  addUnique(errors, "router_version_must_be_0.3");
}

if (!allowedRoutes.includes(routeId)) {
  addUnique(errors, "route_id_not_allowed");
}

if (!allowedPrompts.includes(promptId)) {
  addUnique(errors, "prompt_id_not_allowed");
}

if (allowedRoutes.includes(routeId)) {
  const expectedPromptId = routeToPrompt[routeId];

  if (promptId !== expectedPromptId) {
    addUnique(errors, "route_prompt_mapping_mismatch");
  }
}

if (confidence < 0.7 && routeId !== "ROUTE_NEEDS_HUMAN_REVIEW") {
  addUnique(errors, "low_confidence_must_go_to_human_review");
}

const needsHumanReview =
  routeId === "ROUTE_NEEDS_HUMAN_REVIEW" ||
  confidence < 0.7 ||
  errors.length > 0;

const routerValid =
  errors.length === 0 &&
  routeId !== "ROUTE_NEEDS_HUMAN_REVIEW" &&
