  ai_content_length: aiContent.length,

  ai_model: item.model || "",
  finish_reason: firstChoice.finish_reason || "",
  usage,

  prompt_tokens: usage.prompt_tokens || 0,
  completion_tokens: usage.completion_tokens || 0,
  total_tokens: usage.total_tokens || 0,

  ai_result_parsed: parsedOk,
  parse_ai_result_status: parsedOk ? "parsed" : "failed",
  parse_ai_result_errors: errors,
  parse_ai_result_warnings: warnings,

  errors,
  warnings,

  next_step: parsedOk
    ? "Передать ai_content в AI Result Validator."
    : "Не сохранять результат. Проверить ответ GigaChat Call или потерю parent_result_code.",
},


},
];

const item = $input.first().json;

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

const errors = [...(item.errors || [])];
const warnings = [...(item.warnings || [])];

const aiContent = toText(item.ai_content).trim();
const inputId = toText(item.input_id || "UNKNOWN_INPUT").trim();
const promptId = toText(item.prompt_id || "UNKNOWN_PROMPT").trim();
const routeId = toText(item.route_id || "").trim();
const expectedResultType = toText(item.expected_result_type || "").trim();

const gateChecks = [];

function addCheck(name, status, message) {
  gateChecks.push({
    name,
    status,
    message
  });
}

// 1. Техническая пригодность результата
if (!item.ai_result_parsed) {
  addUnique(errors, "ai_result_not_parsed");
  addCheck("parse_status", "failed", "Parse AI Result не подтвердил успешный разбор ответа.");
} else {
  addCheck("parse_status", "passed", "AI result parsed successfully.");
}

if (!aiContent) {
  addUnique(errors, "ai_content_is_empty");
  addCheck("ai_content", "failed", "AI content пустой.");
} else {
  addCheck("ai_content", "passed", "AI content есть.");
}

if (aiContent.length > 0 && aiContent.length < 500) {
  addUnique(warnings, "ai_content_too_short");
  addCheck("ai_content_length", "warning", "AI content подозрительно короткий.");
} else {
  addCheck("ai_content_length", "passed", `AI content length: ${aiContent.length}.`);
}

if (!inputId || inputId === "UNKNOWN_INPUT") {
  addUnique(errors, "input_id_is_empty_or_unknown");
  addCheck("input_id", "failed", "input_id отсутствует или UNKNOWN.");
} else {
  addCheck("input_id", "passed", "input_id сохранён.");
}

if (!promptId || promptId === "UNKNOWN_PROMPT") {
  addUnique(errors, "prompt_id_is_empty_or_unknown");
  addCheck("prompt_id", "failed", "prompt_id отсутствует или UNKNOWN.");
} else {
  addCheck("prompt_id", "passed", "prompt_id сохранён.");
}

if (!routeId) {
  addUnique(warnings, "route_id_is_empty");
  addCheck("route_id", "warning", "route_id отсутствует.");
} else {
  addCheck("route_id", "passed", "route_id сохранён.");
}

if (!expectedResultType) {
  addUnique(warnings, "expected_result_type_is_empty");
  addCheck("expected_result_type", "warning", "expected_result_type отсутствует.");
} else {
  addCheck("expected_result_type", "passed", "expected_result_type сохранён.");
}

// 2. Минимальный контракт для P001
if (promptId === "P001" || expectedResultType === "requirement_structuring") {
  const minimalSections = [
    "1. Краткое резюме требования",
    "4. Проблемы и неоднозначности",
    "6. Недостающая информация",
    "7. Вопросы к заказчику",
    "9. Риски для разработки и тестирования",
    "12. Черновик улучшенной версии требования",
    "13. Какие тест-кейсы стоит подготовить"
  ];

  const missingSections = [];

  for (const section of minimalSections) {
    if (!aiContent.toLowerCase().includes(section.toLowerCase())) {
      missingSections.push(section);
    }
  }

  if (missingSections.length > 0) {
    addUnique(warnings, "minimal_sections_missing");
    addCheck(
      "minimal_sections",
      "warning",
      `Не найдены некоторые минимальные секции: ${missingSections.join("; ")}`
    );
  } else {
    addCheck("minimal_sections", "passed", "Минимальные секции P001 найдены.");
  }
}

// 3. Мягкие предупреждения по формату
if (/(^|\n)\s*---+\s*(\n|$)/.test(aiContent)) {
  addUnique(warnings, "forbidden_separator_found");
  addCheck(
    "format_separator",
    "warning",
    "Найден разделитель ---. Для финального документа желательно убрать."
  );
}

if (aiContent.includes("|")) {
  addUnique(warnings, "table_pipe_found");
  addCheck(
    "table_pipe",
    "warning",
    "Найден символ |. Возможно, AI использовал таблицу или псевдотаблицу."
  );
}

// 4. Подозрение на смысловые нарушения — только предупреждение, не блокировка
const semanticWarningFragments = [
  "веб-интерфейс",
  "авториз",
  "фильтрац",
  "сортиров",
  "ответственный исполнитель",
  "приоритет"
];

const semanticWarningsFound = semanticWarningFragments.filter(fragment =>
  aiContent.toLowerCase().includes(fragment.toLowerCase())
);

if (semanticWarningsFound.length > 0) {
  addUnique(warnings, "possible_ai_assumptions_found");
  addCheck(
    "semantic_assumptions",
    "warning",
    `В ответе есть возможные AI-допущения: ${semanticWarningsFound.join(", ")}. Нужна ручная проверка.`
  );
}

// 5. Итоговый статус
const technicalOk = errors.length === 0;

let gateStatus = "blocked";
let resultStatus = "blocked";

if (technicalOk && warnings.length === 0) {
  gateStatus = "passed";
  resultStatus = "draft_ready";
}

if (technicalOk && warnings.length > 0) {
  gateStatus = "passed_with_warnings";
  resultStatus = "draft_ready_with_warnings";
}

return [
  {
    json: {
      ...item,

      ai_result_gate_id: `AI-GATE-${inputId}-${promptId}`,

      ai_result_gate_status: gateStatus,
      result_status: resultStatus,

      technical_ok: technicalOk,

      // Черновик можно сохранять, если технически всё разобрано
      ready_for_draft_save: technicalOk,

      // Финальным результатом без человека не считаем
      ready_for_final_save: false,

      // Для учебного процесса Human Review всегда нужен
      human_review_required: true,
      ready_for_human_review: technicalOk,

      gate_checks: gateChecks,

      errors,
      warnings,

      next_step: technicalOk
        ? "Сохранить результат как AI Draft и отправить на Human Review."
        : "Не сохранять результат. Проверить Parse AI Result / GigaChat Call."
    }
  }
];

const item = $input.first().json;

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value);
}

const inputId = toText(item.input_id || "UNKNOWN_INPUT").trim();
const promptId = toText(item.prompt_id || "UNKNOWN_PROMPT").trim();

const warnings = Array.isArray(item.warnings) ? item.warnings : [];
const errors = Array.isArray(item.errors) ? item.errors : [];

const gateChecks = Array.isArray(item.gate_checks) ? item.gate_checks : [];

const warningSummary = gateChecks
  .filter(check => check.status === "warning")
  .map(check => `${check.name}: ${check.message}`)
  .join("\n");

const draftReady = item.ready_for_draft_save === true && errors.length === 0;

const precheckReasonParts = [];

if (item.input_quality) {
  precheckReasonParts.push(`input_quality: ${item.input_quality}`);
}

if (item.input_quality_reason) {
  precheckReasonParts.push(`input_quality_reason: ${item.input_quality_reason}`);
}

if (Array.isArray(item.precheck_warnings) && item.precheck_warnings.length > 0) {
  precheckReasonParts.push(`precheck_warnings: ${item.precheck_warnings.join("; ")}`);
}

if (Array.isArray(item.missing_data) && item.missing_data.length > 0) {
  precheckReasonParts.push(`missing_data: ${item.missing_data.join("; ")}`);
}

const precheckReason = precheckReasonParts.join("\n");

const gateReason = warnings.length > 0
  ? warningSummary || warnings.join("; ")
  : "Human Review required by workflow policy.";

const humanReviewReason = [precheckReason, gateReason]
  .filter(Boolean)
  .join("\n");

const {
  ai_raw_response,
  gigachat_request_body,
  final_prompt,
  ...cleanItem
} = item;

return [
  {
    json: {
      ...cleanItem,

      draft_record_id: `DRAFT-${inputId}-${promptId}`,

      input_id: inputId,
      request_id: item.request_id,
      validation_id: item.validation_id,
      ai_result_id: item.ai_result_id,
      ai_result_gate_id: item.ai_result_gate_id,

      route_id: item.route_id,
      prompt_id: promptId,
      prompt_name: item.prompt_name,
      expected_result_type: item.expected_result_type,

      requirement_text: item.requirement_text,

      ai_content: item.ai_content,
      ai_content_length: item.ai_content_length,

      ai_model: item.ai_model,
      finish_reason: item.finish_reason,

      prompt_tokens: item.prompt_tokens,
      completion_tokens: item.completion_tokens,
      total_tokens: item.total_tokens,

      result_status: item.result_status,
      ai_result_gate_status: item.ai_result_gate_status,

      technical_ok: item.technical_ok,
      ready_for_draft_save: draftReady,
      ready_for_final_save: false,

      human_review_required: true,
      ready_for_human_review: draftReady,
      human_review_reason: humanReviewReason,

      draft_save_status: draftReady ? "ready_to_save" : "blocked",

      errors,
      warnings,

      next_step: draftReady
        ? "Сохранить AI Draft в S2 Output / Automation Log / Human Review queue."
        : "Не сохранять draft. Проверить ошибки AI Result Gate."
    }
  }
];

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }
  return String(value);
}

function joinClean(parts, separator = "; ") {
  return parts
    .map(value => toText(value).trim())
    .filter(Boolean)
    .join(separator);
}

function addUnique(list, value) {
  const text = toText(value).trim();
  if (text && !list.includes(text)) {
    list.push(text);
  }
}

function uniqueList(list) {
  const result = [];

  for (const value of list || []) {
    addUnique(result, value);
  }

  return result;
}

function uniqueLines(text) {
  const seen = new Set();

  return toText(text)
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(line => {
      if (!line) return false;
      if (seen.has(line)) return false;
      seen.add(line);
      return true;
    })
    .join("\n");
}

const appendResult = $input.first().json || {};
const s2 = getNodeJson("Prepare S2 Output Draft");

let errors = Array.isArray(s2.errors) ? [...s2.errors] : [];
let warnings = Array.isArray(s2.warnings) ? [...s2.warnings] : [];

const inputId = toText(s2.input_id || s2["Input ID"]).trim();
const promptId = toText(s2.prompt_id).trim();

// Главное исправление: берём Output ID из Prepare S2 Output Draft, а не из item
const outputId = toText(s2.s2_output_id || s2["Output ID"]).trim();

if (!inputId) {
  addUnique(errors, "automation_log_source_input_id_missing");
}

if (!promptId) {
  addUnique(errors, "automation_log_source_prompt_id_missing");
}

if (!outputId) {
  addUnique(errors, "automation_log_source_output_id_missing");
}

if (!s2.artifact_doc_url) {
  addUnique(errors, "automation_log_artifact_doc_url_missing");
}

if (!s2.s2_output_status) {
  addUnique(errors, "automation_log_s2_output_status_missing");
}

errors = uniqueList(errors);
warnings = uniqueList(warnings);

const nowIso = new Date().toISOString();

const safeInputId = inputId || "SOURCE_CONTEXT_MISSING";
const safePromptId = promptId || "SOURCE_CONTEXT_MISSING";
const safeOutputId = outputId || "SOURCE_CONTEXT_MISSING";

const logId = `LOG-${safeInputId}-${safePromptId}-${Date.now()}`;

const appendLooksOk = Boolean(appendResult && Object.keys(appendResult).length > 0);
const hasErrors = errors.length > 0;
const hasWarnings = warnings.length > 0;

let executionStatus = "Success";

if (hasErrors) {
  executionStatus = "Failed";
} else if (hasWarnings) {
  executionStatus = "Success with warning";
}

const trigger = joinClean([
  "n8n",
  "AI Requirement Processing Workflow",
  promptId ? `Prompt ${promptId}` : "",
  "Google Doc Artifact + S2 Output Draft"
], " / ");

const aiStatus = joinClean([
  s2.result_status,
  s2.ai_result_gate_status,
  s2.ai_model
]);

const storageStatus = joinClean([
  s2.artifact_doc_url ? "google_doc_created" : "google_doc_missing",
  appendLooksOk ? "written_to_s2_output" : "s2_output_append_unknown",
  s2.s2_output_status
]);

const humanReview = s2.human_review_required
  ? "required"
  : "not_required";

const warningText = uniqueLines(
  s2["Предупреждения"] || joinClean([
    warnings.join("; "),
    s2.human_review_reason
  ], "\n")
);

return [
  {
    json: {
      // Поля под таблицу Automation Log
      "Log ID": logId,
      "Input ID": safeInputId,
      "Output ID": safeOutputId,
      "Дата/время запуска": nowIso,
      "Триггер": trigger,
      "Статус выполнения": executionStatus,
      "AI-статус": aiStatus,
      "Storage-статус": storageStatus,
      "Human Review": humanReview,
      "Ошибка": errors.join("; "),
      "Предупреждения": warningText,
      "Следующий шаг": s2["Следующий шаг"] || s2.next_step || "Проверить AI Draft artifact и выполнить Human Review.",

      // алиасы для Google Sheets mapping
      log_id: logId,
      input_id: safeInputId,
      output_id: safeOutputId,
      started_at: nowIso,

      trigger,
      execution_status: executionStatus,
      ai_status: aiStatus,
      storage_status: storageStatus,
      human_review: humanReview,
      error: errors.join("; "),
      warnings: warningText,
      next_step: s2["Следующий шаг"] || s2.next_step || "Проверить AI Draft artifact и выполнить Human Review.",

      // debug-поля, в таблицу можно не маппить
      artifact_doc_url: s2.artifact_doc_url,
      artifact_doc_id: s2.artifact_doc_id,
      s2_output_status: s2.s2_output_status,
      append_result_keys: Object.keys(appendResult || {}).join("; "),
      prompt_id: safePromptId,
      route_id: s2.route_id,
      expected_result_type: s2.expected_result_type
    }
  }
];

const item = $input.first().json || {};

function toText(value) {
  if (value === null || value === undefined) {
    return "";
  }
  return String(value);
}

function joinClean(parts, separator = "\n") {
  return parts
    .map(value => toText(value).trim())
    .filter(Boolean)
    .join(separator);
}

function uniqueArray(values) {
  const result = [];
  const seen = new Set();

  for (const value of values) {
    if (value === null || value === undefined) continue;

    const text = String(value).trim();
    if (!text) continue;
    if (seen.has(text)) continue;

    seen.add(text);
    result.push(text);
  }

  return result;
}

function limitText(text, maxLength = 80) {
  const value = toText(text).replace(/\s+/g, " ").trim();

  if (value.length <= maxLength) {
    return value;
  }

  return value.slice(0, maxLength).trim() + "…";
}

function getResultTypeTitle(item) {
  const promptId = toText(item.prompt_id).trim();
  const routeId = toText(item.route_id).trim();
  const expectedType = toText(item.expected_result_type).trim();

  const byPromptId = {
    P001: "Анализ требования",
    P002: "Тест-кейсы",
    P003: "Вопросы к заказчику",
    P004: "User Story и Acceptance Criteria",
    P005: "Bug Report",
    P006: "Чек-лист",
    P007: "Ревью требования",
    P008: "Декомпозиция требования",
    P009: "Портфолио-кейс",
    P010: "Маршрутизация промпта",
    P011: "Проектирование AI-процесса"
  };

  const byExpectedType = {
    requirement_structuring: "Анализ требования",
    test_cases: "Тест-кейсы",
    customer_questions: "Вопросы к заказчику",
    user_story_acceptance_criteria: "User Story и Acceptance Criteria",
    bug_report: "Bug Report",
    checklist: "Чек-лист",
    requirement_review: "Ревью требования",
    requirement_decomposition: "Декомпозиция требования",
    portfolio_case: "Портфолио-кейс",
    router_decision: "Маршрутизация промпта",
    process_design: "Проектирование AI-процесса"
  };

  const byRouteId = {
    ROUTE_REQUIREMENT_STRUCTURING: "Анализ требования",
    ROUTE_CUSTOMER_QUESTIONS: "Вопросы к заказчику",
    ROUTE_REQUIREMENT_REVIEW: "Ревью требования",
    ROUTE_REQUIREMENT_DECOMPOSITION: "Декомпозиция требования",
    ROUTE_TEST_DESIGN: "Тестовый артефакт",
    ROUTE_PROCESS_DESIGN: "Проектирование AI-процесса",
    ROUTE_PORTFOLIO_CASE: "Портфолио-кейс"
  };

  return (
    byPromptId[promptId] ||
    byExpectedType[expectedType] ||
    byRouteId[routeId] ||
    "AI-результат"
  );
}

function getHumanTopic(item) {
  const explicitTitle = toText(
    item.human_topic ||
    item.result_topic ||
    item.requirement_title ||
    item.input_title ||
    ""
  ).trim();

  if (explicitTitle) {
    return limitText(explicitTitle, 80);
  }

  const requirementText = toText(item.requirement_text).toLowerCase();
  if (
    requirementText.includes("справочник") &&
    requirementText.includes("материал")
  ) {
    return "справочник материалов";
  }
  if (
    requirementText.includes("прогресс") &&
    requirementText.includes("ремонт") &&
    requirementText.includes("дефект")
  ) {
    return "прогресс ремонта и дефекты";
  }

  if (requirementText.includes("ремонт") && requirementText.includes("комнат")) {
    return "ремонт комнат";
  }

  if (requirementText.includes("дефект")) {
    return "дефекты ремонта";
  }

  const cleaned = toText(item.requirement_text)
    .replace(/[.!?]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();

  if (cleaned) {
    const words = cleaned.split(" ").slice(0, 8).join(" ");
    return limitText(words, 80);
  }

  return "без названия";
}

const now = new Date();
const nowIso = now.toISOString();
const safeTs = nowIso.replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");

const inputId = toText(item.input_id || "UNKNOWN_INPUT").trim();
const promptId = toText(item.prompt_id || "UNKNOWN_PROMPT").trim();

const artifactFolderId = "YOUR_ARTIFACT_FOLDER_ID";
const artifactFolderName = "AI Requirements Workflow / Artifacts";
const artifactFolderUrl = "https://drive.google.com/drive/folders/YOUR_ARTIFACT_FOLDER_ID";

const resultTypeTitle = getResultTypeTitle(item);
const humanTopic = getHumanTopic(item);

const resultTitle = `${resultTypeTitle} — ${humanTopic}`;
const docTitle = `AI Draft — ${resultTitle} — ${safeTs}`;

const warnings = uniqueArray([
  ...(Array.isArray(item.warnings) ? item.warnings : []),
  ...(Array.isArray(item.precheck_warnings) ? item.precheck_warnings : [])
]);

const errors = uniqueArray([
  ...(Array.isArray(item.errors) ? item.errors : [])
]);

const docContent = joinClean([
  `AI Draft Artifact`,
  ``,
  `Result title: ${resultTitle}`,
  `Input ID: ${inputId}`,
  `Prompt ID: ${promptId}`,
  `Prompt name: ${toText(item.prompt_name)}`,
  `Route ID: ${toText(item.route_id)}`,
  `Expected result type: ${toText(item.expected_result_type)}`,
  `Created at: ${nowIso}`,
  ``,
  `Result status: ${toText(item.result_status)}`,
  `AI gate status: ${toText(item.ai_result_gate_status)}`,
  `Technical OK: ${item.technical_ok === true}`,
  `Human Review required: ${item.human_review_required === true}`,
  ``,
  `Input Precheck:`,
  `Input quality: ${toText(item.input_quality)}`,
  `Input quality score: ${toText(item.input_quality_score)}`,
  `Input quality reason: ${toText(item.input_quality_reason)}`,
  `Requirement word count: ${toText(item.requirement_word_count)}`,
  `Input signal score: ${toText(item.input_signal_score)}`,
  `Precheck status: ${toText(item.precheck_status)}`,
  `Precheck warnings: ${Array.isArray(item.precheck_warnings) ? item.precheck_warnings.join("; ") : "none"}`,
  `Missing data: ${Array.isArray(item.missing_data) ? item.missing_data.join("; ") : "none"}`,
  `Safe routes: ${Array.isArray(item.safe_routes) ? item.safe_routes.join("; ") : "none"}`,
  `Blocked routes: ${Array.isArray(item.blocked_routes) ? item.blocked_routes.join("; ") : "none"}`,
  ``,
  `Warnings: ${warnings.join("; ") || "none"}`,
  `Errors: ${errors.join("; ") || "none"}`,
  ``,
  `Human Review reason:`,
  toText(item.human_review_reason || "Human Review required by workflow policy."),
  ``,
  `Source requirement:`,
  toText(item.requirement_text),
  ``,
  `AI Draft content:`,
  toText(item.ai_content),
  ``,
  `Note: This document is an AI draft artifact. It is not a final approved requirement or final analytical conclusion until Human Review is completed.`
]);

return [
  {
    json: {
      ...item,

      artifact_id: `ART-${inputId}-${promptId}-${Date.now()}`,

      result_type_title: resultTypeTitle,
      human_topic: humanTopic,
      result_title: resultTitle,

      artifact_title: docTitle,
      artifact_content: docContent,
      artifact_created_at: nowIso,

      artifact_status: "ready_to_create_google_doc",
      need_google_doc: true,

      artifact_folder_id: artifactFolderId,
      artifact_folder_name: artifactFolderName,
      artifact_folder_url: artifactFolderUrl,

      errors,
      warnings,

      next_step: "Создать Google Doc artifact с artifact_title и artifact_content. Затем передать ссылку в S2 Output Draft."
    }
  }
];

parameters.jsonBody:
={{
  {
    requests: [
      {
        insertText: {
