  return String(value);
}

function firstNotEmpty(values) {
  for (const value of values) {
    const text = toText(value).trim();
    if (text) return text;
  }
  return "";
}

function addUnique(list, value) {
  if (!list.includes(value)) {
    list.push(value);
  }
}

