  createdDoc.documentId,
  createdDoc.document_id,
  createdDoc.id,
  createdDoc.fileId,
  createdDoc.file_id
]);

const artifactDocUrl = firstNotEmpty([
  createdDoc.webViewLink,
  createdDoc.webContentLink,
  createdDoc.documentUrl,
  createdDoc.url,
  artifactDocId ? `https://docs.google.com/document/d/${artifactDocId}/edit` : ""
]);

if (!artifactDocId) {
  addUnique(errors, "artifact_doc_id_missing");
}

if (!artifactDocUrl) {
  addUnique(errors, "artifact_doc_url_missing");
}

const insertOk = Array.isArray(insertResult.replies) || Object.keys(insertResult || {}).length > 0;

if (!insertOk) {
  addUnique(errors, "artifact_content_insert_unknown");
}

const artifactCreated = Boolean(artifactDocUrl) && insertOk;

return [
  {
    json: {
      ...source,

      artifact_doc_id: artifactDocId,
      artifact_doc_url: artifactDocUrl,
      artifact_folder_id: source.artifact_folder_id,
