    }
  }
];

const item = $input.first().json || {};

function toText(value) {
if (value === null || value === undefined) {
return "";
}

return String(value);
}

function joinClean(parts, separator = "\n") {
return parts
.map(value => toText(value).trim())
.filter(Boolean)
.join(separator);
}

function addUnique(list, value) {
if (!list.includes(value)) {
list.push(value);
}
}

function uniqueList(list) {
const result = [];

for (const value of list || []) {
if (value !== null && value !== undefined && String(value).trim()) {
addUnique(result, String(value).trim());
}
}

return result;
}

function normalizeIdPart(value) {
return String(value || "")
.trim()
.replace(/[^a-zA-Z0-9А-Яа-я_-]/g, "")
.slice(0, 24);
}

function cleanText(value) {
return String(value || "")
.replace(/\r/g, "")
.replace(/\n+/g, " ")
.replace(/\s+/g, " ")
.trim();
}

function makeShortInputId(inputId) {
const text = normalizeIdPart(inputId);

if (!text) {
return "UNKNOWN";
}

return text.length > 18 ? text.slice(0, 18) : text;
}

function makeS2OutputId(item) {
const promptId = normalizeIdPart(item.prompt_id || "UNKNOWN_PROMPT");
