return `ВХ-${suffix}`;
}

function getNumericInputCode(inputCode, inputId) {
const fromCode = String(inputCode || "").replace(/\D/g, "");

if (fromCode) {
return fromCode;
}

const fromId = String(inputId || "").replace(/\D/g, "");

return fromId.slice(-6) || String(Date.now()).slice(-6);
}

function parseVersionFromResultCode(value) {
const match = String(value || "").trim().match(/.(\d+)$/);

if (!match) {
return 0;
}

const version = Number(match[1]);

return Number.isFinite(version) ? version : 0;
}

function isChildProcessMode(processMode) {
const mode = cleanText(processMode);

return (
mode === "continue" ||
mode === "continue_with_notes" ||
mode === "rerun" ||
mode === "rerun_ai" ||
mode === "input_fix"
);
}

function makeResultVersion(item, parentResultCode, processMode) {
const mode = cleanText(processMode || item.process_mode || "initial");

if (isChildProcessMode(mode) && parentResultCode) {
const parentVersion = parseVersionFromResultCode(parentResultCode);


if (parentVersion > 0) {
  return parentVersion + 1;
}

const previousVersion = Number(
  item.next_step_context?.result_version ||
