  item.previous_result_version ||
  item.result_version
);

if (Number.isFinite(previousVersion) && previousVersion > 0) {
  return previousVersion + 1;
}

return 2;


}

const rerunAttempt = Number(
item.rerun_attempt ||
item.reviewed_result_context?.rerun_attempt ||
item.next_step_context?.rerun_attempt
);

if (
(mode === "rerun" || mode === "rerun_ai") &&
Number.isFinite(rerunAttempt) &&
rerunAttempt > 0
) {
return rerunAttempt + 1;
}

const explicitVersion = Number(item.result_version);

if (Number.isFinite(explicitVersion) && explicitVersion > 0) {
return explicitVersion;
}

return 1;
}

function makeResultCode(inputCode, inputId, version) {
const codeNumber = getNumericInputCode(inputCode, inputId);

