function normalizeForSearch(value) {
  return toText(value)
    .toLowerCase()
    .replace(/ё/g, "е")
    .replace(/[«»"']/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function hasAny(text, fragments) {
  const normalizedText = normalizeForSearch(text);

  return fragments.some(fragment => {
    const normalizedFragment = normalizeForSearch(fragment);
    return normalizedFragment && normalizedText.includes(normalizedFragment);
  });
}

let errors = Array.isArray(item.errors) ? [...item.errors] : [];
