const item = $json || {};

const sourceContext =
$("PROD — Merge HR Context After Registry Lookup").first().json || {};

function toText(value) {
if (value === null || value === undefined) return "";
return String(value).trim();
}

function deepText(value) {
if (value === null || value === undefined) return "";

if (typeof value === "string") {
return value;
}

if (Array.isArray(value)) {
return value.map(deepText).filter(Boolean).join("\n");
}

if (typeof value === "object") {
const parts = [];


for (const [key, val] of Object.entries(value)) {
  if (
    [
      "content",
      "text",
      "body",
      "paragraph",
      "elements",
      "textRun",
      "textContent",
      "value",
      "plainText",
      "markdown",
      "documentText"
    ].includes(key)
  ) {
    parts.push(deepText(val));
  } else if (typeof val === "object") {
    parts.push(deepText(val));
  }
}

return parts.filter(Boolean).join("\n");


}

return "";
}

function extractAiDraft(fullText) {
const text = toText(fullText);

if (!text) return "";

const markers = [
"AI Draft content:",
"AI Draft content",
"AI Draft:",
"AI Draft",
"Черновик AI:",
"Черновик AI",
"Результат AI:",
"Результат AI",
"AI-результат:",
"AI-результат"
];

for (const marker of markers) {
const index = text.toLowerCase().indexOf(marker.toLowerCase());


if (index >= 0) {
  const afterMarker = text.slice(index + marker.length).trim();

  const stopMarkers = [
    "\nHuman Review",
    "\nПроверка человеком",
    "\nMetadata",
    "\nМетаданные",
    "\nS2 Output",
    "\nAutomation Log"
  ];

  let endIndex = afterMarker.length;

  for (const stopMarker of stopMarkers) {
    const stopIndex = afterMarker.toLowerCase().indexOf(stopMarker.toLowerCase());
    if (stopIndex >= 0 && stopIndex < endIndex) {
      endIndex = stopIndex;
    }
  }

  return afterMarker.slice(0, endIndex).trim();
}


}

// Если маркер не найден, не падаем: берём весь читаемый текст документа.
// Это лучше, чем потерять Draft, но ниже добавим warning.
return text;
}

const fullDocText = deepText(item);
const reviewedAiDraftText = extractAiDraft(fullDocText);

const previousContext =
sourceContext.reviewed_result_context || {};

const errors = [
...(Array.isArray(sourceContext.errors) ? sourceContext.errors : []),
];

const warnings = [
...(Array.isArray(sourceContext.warnings) ? sourceContext.warnings : []),
];

if (!reviewedAiDraftText) {
errors.push("reviewed_ai_draft_text_is_empty");
}

if (
reviewedAiDraftText &&
!fullDocText.toLowerCase().includes("ai draft")
) {
warnings.push("ai_draft_marker_not_found_full_doc_text_used");
}

const reviewedResultContext = {
...previousContext,
reviewed_ai_draft_text: reviewedAiDraftText,
};

const contextReady =
errors.length === 0 &&
Boolean(reviewedResultContext.input_id) &&
Boolean(reviewedResultContext.reviewed_result_code) &&
Boolean(reviewedResultContext.reviewed_artifact_url) &&
Boolean(reviewedResultContext.reviewed_ai_draft_text) &&
Boolean(reviewedResultContext.human_review_decision);

